package com.starfloat.overlay;
import android.app.*;import android.content.*;import android.graphics.Color;import android.media.projection.MediaProjectionManager;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 static final int CAPTURE=42, PICK_IMAGE=43; int[] colors={0xFFB58CFF,0xFFB6FF4A,0xFF45E6FF,Color.WHITE,0xFFFF68C8,0xFFFFA24A}; String[] names={"Purple","Green","Cyan","White","Pink","Orange"}; SeekBar size,border; Spinner color;
 public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,24,24,24);l.setBackgroundColor(0xFF080B12); ScrollView sc=new ScrollView(this);sc.addView(l);
 TextView t=new TextView(this);t.setText("✦ STARFLOAT");t.setTextSize(28);t.setTextColor(0xFFB58CFF);t.setTypeface(null,1);l.addView(t);label(l,"Floating ball • Quick paste • Screenshot");
 label(l,"BALL COLOUR");color=new Spinner(this);color.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));l.addView(color);color.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?>a,View v,int p,long id){save();}public void onNothingSelected(android.widget.AdapterView<?>a){}});
 label(l,"BALL SIZE");size=new SeekBar(this);size.setMax(100);size.setProgress(32);l.addView(size);size.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean u){save();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});
 label(l,"BORDER THICKNESS");border=new SeekBar(this);border.setMax(12);border.setProgress(3);l.addView(border);border.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean u){save();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});
 add(l,"1 • Allow display over other apps",v->{if(!Settings.canDrawOverlays(this))startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));});
 add(l,"2 • Enable quick-paste Accessibility",v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));
 add(l,"Choose image for inside the ball (optional)",v->{Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.setType("image/*");pick.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(pick,PICK_IMAGE);});
 add(l,"3 • Enable screenshot capture",v->{MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);startActivityForResult(m.createScreenCaptureIntent(),CAPTURE);});
 add(l,"START FLOATING BALL",v->{save();if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));return;}if(Build.VERSION.SDK_INT>=26)startForegroundService(new Intent(this,FloatingService.class));else startService(new Intent(this,FloatingService.class));});
 add(l,"STOP FLOATING BALL",v->stopService(new Intent(this,FloatingService.class)));
 label(l,"Single tap: paste clipboard text into a focused field. Double tap: screenshot. Drag to × to stop. Android permission prompts are required.");setContentView(sc);}
 void label(LinearLayout l,String s){TextView t=new TextView(this);t.setText(s);t.setTextColor(0xFFCDD3E0);t.setPadding(0,14,0,6);l.addView(t);} void add(LinearLayout l,String s,android.view.View.OnClickListener c){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(-1);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFF28243A));l.addView(b);b.setOnClickListener(c);} void save(){if(size==null||border==null||color==null)return;getSharedPreferences("sf",0).edit().putInt("size",size.getProgress()+30).putInt("border",border.getProgress()).putInt("color",colors[color.getSelectedItemPosition()]).apply();sendBroadcast(new Intent("com.starfloat.overlay.UPDATE"));}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==PICK_IMAGE&&c==RESULT_OK&&d!=null&&d.getData()!=null){try{getContentResolver().takePersistableUriPermission(d.getData(),Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}getSharedPreferences("sf",0).edit().putString("image",d.getData().toString()).apply();sendBroadcast(new Intent("com.starfloat.overlay.UPDATE"));Toast.makeText(this,"Ball image selected",0).show();return;}if(r==CAPTURE&&c==RESULT_OK&&d!=null){FloatingService.projectionResult=c;FloatingService.projectionData=d;Toast.makeText(this,"Capture permission granted; start the ball again",0).show();}}
}